<script lang="ts">
  import { onMount } from 'svelte';
  import { get } from 'svelte/store';
  import { gsap } from 'gsap';
  import { analyzeView, getPoseMode, startGait, stopGait, uploadFrame, type CompactFrame, type PoseKeypoint, type PoseMode } from '../../lib/api';
  import { PoseTracker, detectPose, poseStatus } from '../../lib/pose';
  import { saveCloudResult } from '../../lib/cloud-results';
  import { activityType, cameraViews, captureViews, sessionId, stopCaptureViews, testDuration, type ActivityType, type CameraView, type CaptureView } from '../../lib/stores/session';
  import { validatePersonProfile } from '../../lib/stores/person';

  let { onExit = () => {}, onComplete = (_sessionId: string) => {} }: { onExit?: () => void; onComplete?: (sessionId: string) => void } = $props();
  const config: Record<ActivityType, { instruction: string }> = { 'Normal Walk': { instruction: 'Walk toward the centre camera at your natural pace.' }, 'Fast Walk': { instruction: 'Move briskly while keeping your whole body in each active frame.' }, Run: { instruction: 'Run smoothly through the marked capture zone.' }, Balance: { instruction: 'Stand tall and hold steady in every active view.' }, 'Toe Walk': { instruction: 'Walk forward on your toes with both feet visible.' } };
  const connections = [[11,13],[13,15],[12,14],[14,16],[11,12],[11,23],[12,24],[23,24],[23,25],[25,27],[24,26],[26,28],[27,29],[29,31],[28,30],[30,32]];
  type FrameVideo = HTMLVideoElement & { requestVideoFrameCallback?: (callback: (now: number) => void) => number; cancelVideoFrameCallback?: (id: number) => void; };
  interface Panel { cloudFrames: CompactFrame[]; tracker?: PoseTracker; capture: CaptureView; video?: FrameVideo; canvas?: HTMLCanvasElement; scratch: HTMLCanvasElement; points: PoseKeypoint[]; bodyDetected: boolean; sent: number; acked: number; queued: number; failed: number; sequence: number; lastCapture: number; callback: number; timer?: ReturnType<typeof setInterval>; trails: Array<{ x: number; y: number; hue: string; life: number }>; }
  interface Job { view: CameraView; blob: Blob; seq: number; t: number; attempts: number; }

  let panels = $state<Partial<Record<CameraView, Panel>>>({});
  let poseMode = $state<PoseMode>('server');
  let recording = $state(false), finishing = $state(false), countdown = $state<number | null>(null), elapsed = $state(0), error = $state(''), backendState = $state<'ready' | 'offline'>('ready');
  let activeView = $state<CameraView>('left');
  let animationFrame = 0, readinessTimer: ReturnType<typeof setInterval> | undefined, elapsedTimer: ReturnType<typeof setInterval> | undefined, countdownTimer: ReturnType<typeof setInterval> | undefined, clockOrigin = 0, uploadActive = 0, disposed = false;
  const queue: Job[] = [], maxUploads = 3;
  const currentDuration = () => get(testDuration);
  const formatted = (seconds: number) => {
    const safe = Math.min(currentDuration(), Math.floor(seconds));
    return `${String(Math.floor(safe / 60)).padStart(2, '0')}:${String(safe % 60).padStart(2, '0')}`;
  };
  const active = () => cameraViews.filter((view) => panels[view]);
  const panel = (view: CameraView) => panels[view];
  const fullBody = (item?: Panel) => !!item?.bodyDetected && [11, 12, 23, 24, 27, 28, 31, 32].every((index) => (item.points[index]?.visibility ?? 0) >= .5);
  const canStart = () => active().length > 0 && active().every((view) => fullBody(panel(view)));
  function bindVideo(node: FrameVideo, view: CameraView) { const item = panel(view); if (item) { item.video = node; node.srcObject = item.capture.stream; void node.play().catch(() => { error = `${item.capture.label} could not play.`; }); } return { destroy() { const current = panel(view); if (current?.video === node) current.video = undefined; } }; }
  function bindCanvas(node: HTMLCanvasElement, view: CameraView) { const item = panel(view); if (item) item.canvas = node; return { destroy() { const current = panel(view); if (current?.canvas === node) current.canvas = undefined; } }; }
  function rotate(view: CameraView) { if (recording || countdown !== null) return; const item = panel(view); if (item) { item.capture.rotation = (item.capture.rotation + 90) % 360; panels = { ...panels }; } }
  async function fullscreen() { try { if (!document.fullscreenElement) await document.documentElement.requestFullscreen?.(); } catch { /* Fixed layout remains the fallback. */ } }
  async function exitFullscreen() { try { if (document.fullscreenElement) await document.exitFullscreen(); } catch { /* no-op */ } }
  function prepareCanvas(item: Panel) {
    const video = item.video; if (!video) return null; const sourceWidth = video.videoWidth || item.capture.width || 1280, sourceHeight = video.videoHeight || item.capture.height || 720, rotated = item.capture.rotation % 180 !== 0;
    item.scratch.width = rotated ? sourceHeight : sourceWidth; item.scratch.height = rotated ? sourceWidth : sourceHeight; const context = item.scratch.getContext('2d'); if (!context) return null;
    context.save(); context.clearRect(0, 0, item.scratch.width, item.scratch.height); if (rotated) { context.translate(item.scratch.width / 2, item.scratch.height / 2); context.rotate(item.capture.rotation * Math.PI / 180); context.drawImage(video, -sourceWidth / 2, -sourceHeight / 2, sourceWidth, sourceHeight); } else { if (item.capture.rotation === 180) { context.translate(sourceWidth, sourceHeight); context.rotate(Math.PI); } context.drawImage(video, 0, 0, sourceWidth, sourceHeight); } context.restore(); return context;
  }
  function encode(item: Panel) { return new Promise<Blob | null>((resolve) => { prepareCanvas(item); item.scratch.toBlob(resolve, 'image/jpeg', .72); }); }
  function enqueue(view: CameraView, blob: Blob, t: number) { const item = panel(view); if (!item) return; if (queue.length > 24) { const dropped = queue.shift(); if (dropped) { const droppedPanel = panel(dropped.view); if (droppedPanel) { droppedPanel.failed += 1; droppedPanel.queued -= 1; } } } queue.push({ view, blob, seq: item.sequence++, t, attempts: 0 }); item.queued += 1; pump(); }
  function pump() { const id = get(sessionId); if (!id) return; while (uploadActive < maxUploads && queue.length) { const job = queue.shift(); if (!job) return; const item = panel(job.view); if (!item) continue; item.queued -= 1; uploadActive += 1; void uploadFrame(id, job.blob, { view: job.view, seq: job.seq, timestampMs: job.t }).then((response) => { const target = panel(job.view); if (!target) return; target.acked += 1; target.points = response.keypoints ?? []; target.bodyDetected = response.bodyDetected ?? false; backendState = 'ready'; }).catch(() => { const target = panel(job.view); backendState = 'offline'; if (!target) return; if (job.attempts < 2 && recording) { job.attempts += 1; target.queued += 1; setTimeout(() => { queue.push(job); pump(); }, 180 * 2 ** job.attempts); } else target.failed += 1; }).finally(() => { uploadActive -= 1; pump(); }); } }
  async function capture(view: CameraView, timestamp: number, upload = true) { const item = panel(view); if (!item?.video || item.video.readyState < HTMLMediaElement.HAVE_CURRENT_DATA) return; if (poseMode === 'browser') { const keypoints = await detectPose(item.video, timestamp); item.points = keypoints; item.bodyDetected = keypoints.length > 0; if (upload) { item.sent += 1; item.acked += 1; item.cloudFrames.push({ t: Math.max(0, timestamp - clockOrigin) / 1000, timestamp: new Date().toISOString(), seq: item.sequence++, keypoints }); } if (poseStatus()) backendState = 'offline'; return; } const blob = await encode(item); if (!blob || disposed) return; if (upload) { item.sent += 1; enqueue(view, blob, timestamp); } else { try { const response = await uploadFrame(get(sessionId) || '', blob, { view, seq: item.sequence++, timestampMs: performance.now() }); item.points = response.keypoints ?? []; item.bodyDetected = response.bodyDetected ?? false; } catch { backendState = 'offline'; } } }
  function startLoop(view: CameraView) { const item = panel(view); if (!item?.video) return; const video = item.video; const callback = (now: number) => { if (!recording) return; if (now - item.lastCapture >= 100) { item.lastCapture = now; void capture(view, Math.max(0, now - clockOrigin)); } item.callback = video.requestVideoFrameCallback?.(callback) ?? 0; }; if (video.requestVideoFrameCallback) item.callback = video.requestVideoFrameCallback(callback); else item.timer = setInterval(() => void capture(view, performance.now() - clockOrigin), 100); }
  function stopLoops() { active().forEach((view) => { const item = panel(view); const video = item?.video; if (item?.callback && video?.cancelVideoFrameCallback) video.cancelVideoFrameCallback(item.callback); if (item?.timer) clearInterval(item.timer); if (item) { item.callback = 0; item.timer = undefined; } }); }
  async function begin() {
    const id = get(sessionId); if (!id) { error = 'No active GAIT session. Return to camera setup.'; return; }
    error = ''; await fullscreen();
    try { if (poseMode === 'server') await startGait(id, get(activityType), undefined, active().map((view) => { const item = panel(view)!; return { view, cameraLabel: item.capture.label, rotation: item.capture.rotation, width: item.capture.width, height: item.capture.height, fps: item.capture.fps }; }), validatePersonProfile(), currentDuration());
    } catch (failure) { error = failure instanceof Error ? failure.message : 'The backend could not start this session.'; return; }
    countdown = 3; gsap.fromTo('.countdown', { scale: 5, opacity: 0 }, { scale: .5, opacity: 1, duration: .6, ease: 'power4.out' });
    countdownTimer = setInterval(() => { if (countdown === null) return; if (countdown <= 1) { if (countdownTimer) clearInterval(countdownTimer); countdown = null; recording = true; clockOrigin = performance.now(); elapsedTimer = setInterval(() => { elapsed = (performance.now() - clockOrigin) / 1000; if (elapsed >= currentDuration()) void finish(); }, 60); active().forEach(startLoop); return; } countdown -= 1; gsap.fromTo('.countdown', { scale: 4, opacity: 0 }, { scale: .5, opacity: 1, duration: .48, ease: 'power4.out' }); }, 1000);
  }
  async function finish() { if (finishing) return; finishing = true; recording = false; stopLoops(); if (elapsedTimer) clearInterval(elapsedTimer); const deadline = performance.now() + 3000; while ((queue.length || uploadActive) && performance.now() < deadline) await new Promise((resolve) => setTimeout(resolve, 40)); const id = get(sessionId); try { if (id && poseMode === 'server') await stopGait(id, active().reduce((out, view) => { out[view] = panel(view)?.sent ?? 0; return out; }, {} as Partial<Record<CameraView, number>>)); if (id && poseMode === 'browser') { const person = validatePersonProfile(); const analyses = await Promise.all(active().map(async (view) => { const item = panel(view)!; return analyzeView({ sessionId: id, activityType: get(activityType), person, durationSec: currentDuration(), view, metadata: { view, cameraLabel: item.capture.label, rotation: item.capture.rotation, width: item.capture.width, height: item.capture.height, fps: item.capture.fps }, frames: item.cloudFrames, sentCount: item.sent }); })); const preferred = analyses.find((item) => item.views?.[0]?.view === 'left') ?? analyses.find((item) => item.views?.[0]?.view === 'right') ?? analyses[0]; const metrics = { ...preferred.metrics }; for (const key of Object.keys(metrics) as Array<keyof typeof metrics>) { if (metrics[key].available) continue; const alternative = analyses.map((item) => item.metrics[key]).find((item) => item?.available); if (alternative) metrics[key] = alternative; } const merged = { ...preferred, metrics, frameCount: analyses.reduce((sum, item) => sum + item.frameCount, 0), framesReceived: analyses.reduce((sum, item) => sum + item.framesReceived, 0), detectedFrames: analyses.reduce((sum, item) => sum + item.detectedFrames, 0), views: analyses.flatMap((item) => item.views ?? []), landmarksByView: Object.assign({}, ...analyses.map((item) => item.landmarksByView ?? {})), message: 'Analyzed in browser pose mode.' }; await saveCloudResult(merged); } stopCaptureViews(); await exitFullscreen(); if (id) onComplete(id); } catch (failure) { error = failure instanceof Error ? failure.message : 'The test stopped, but analysis could not begin.'; finishing = false; } }
  function exit() { if (recording || countdown !== null) { error = 'Finish the active test before leaving.'; return; } stopCaptureViews(); void exitFullscreen(); onExit(); }
  function drawPanel(item: Panel) { const canvas = item.canvas, video = item.video; if (!canvas || !video) return; const width = video.videoWidth || 720, height = video.videoHeight || 1280; if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; } const context = canvas.getContext('2d'); if (!context) return; context.clearRect(0, 0, width, height); const points = item.points; if (!item.bodyDetected) return; const left = points[31], right = points[32]; if (left?.visibility >= .4) item.trails.push({ x: left.x, y: left.y, hue: '#00c8f5', life: 1 }); if (right?.visibility >= .4) item.trails.push({ x: right.x, y: right.y, hue: '#ff7a00', life: 1 }); item.trails.splice(0, Math.max(0, item.trails.length - 45)); item.trails.forEach((trail) => { trail.life -= .018; context.globalAlpha = Math.max(0, trail.life) * .45; context.fillStyle = trail.hue; context.beginPath(); context.ellipse(trail.x * width, trail.y * height, 12, 5, 0, 0, Math.PI * 2); context.fill(); }); context.globalAlpha = 1; context.strokeStyle = '#00e5ff'; context.fillStyle = '#00e5ff'; context.lineWidth = Math.max(2, width / 350); connections.forEach(([a, b]) => { const start = points[a], end = points[b]; if (!start || !end || start.visibility < .4 || end.visibility < .4) return; context.beginPath(); context.moveTo(start.x * width, start.y * height); context.lineTo(end.x * width, end.y * height); context.stroke(); }); points.forEach((point) => { if (point.visibility >= .4) { context.beginPath(); context.arc(point.x * width, point.y * height, Math.max(3, width / 260), 0, Math.PI * 2); context.fill(); } }); }
  function draw() { active().forEach((view) => { const item = panel(view); if (item) drawPanel(item); }); animationFrame = requestAnimationFrame(draw); }
  onMount(() => { void getPoseMode().then((mode) => { poseMode = mode; }); const supplied = get(captureViews); const next: Partial<Record<CameraView, Panel>> = {}; cameraViews.forEach((view) => { const capture = supplied[view]; if (capture) next[view] = { cloudFrames: [], capture, scratch: document.createElement('canvas'), points: [], bodyDetected: false, sent: 0, acked: 0, queued: 0, failed: 0, sequence: 0, lastCapture: 0, callback: 0, trails: [] }; }); panels = next; activeView = active()[0] ?? 'left'; if (!active().length) { error = 'No live camera streams are available. Return to setup and try again.'; return; } readinessTimer = setInterval(() => { if (!recording && countdown === null) active().forEach((view) => void capture(view, performance.now(), false)); }, 650); draw(); gsap.from('.activity-ui', { y: 20, opacity: 0, duration: .55, stagger: .06, ease: 'power4.out' }); return () => { disposed = true; cancelAnimationFrame(animationFrame); if (readinessTimer) clearInterval(readinessTimer); if (elapsedTimer) clearInterval(elapsedTimer); if (countdownTimer) clearInterval(countdownTimer); stopLoops(); if (!finishing) stopCaptureViews(); }; });
</script>

<main class="activity-shell">
  <div class:one={active().length === 1} class:two={active().length === 2} class="panel-grid">{#each active() as view}{@const item = panel(view)!}<section class:active={activeView === view} class="capture-panel"><video use:bindVideo={view} autoplay muted playsinline class:mirrored={item.capture.mirrored} style={`--rotation:${item.capture.rotation}deg`}></video><canvas use:bindCanvas={view}></canvas><div class="video-label"><b>{view.toUpperCase()}</b><span class:detected={item.bodyDetected}><i></i>{item.bodyDetected ? 'BODY FOUND' : 'FINDING BODY'}</span><small>{Math.round(item.capture.fps ?? 0)} FPS</small></div><button class="rotate" onclick={() => rotate(view)} disabled={recording || countdown !== null}>↻</button><button class="mobile-view" onclick={() => activeView = view}>{view.toUpperCase()}</button></section>{/each}</div>
  <div class="activity-ui top"><button class="wordmark" onclick={exit}>GAIT<span>®</span></button><div class="timer-readout"><small>{recording ? 'RECORDING' : 'READY TO RECORD'}</small><strong>{formatted(elapsed)}<i> / {formatted(currentDuration())}</i></strong></div><div><span class:offline={backendState === 'offline'}>{backendState === 'offline' ? 'OFFLINE' : 'BACKEND LIVE'}</span><button onclick={exit}>Exit test</button></div></div>
  <div class="activity-ui centre"><div class="silhouette" aria-hidden="true"></div><p class="instruction">{config[get(activityType)].instruction}</p>{#if active().some((view) => !panel(view)?.bodyDetected)}<span class="warning">Step back — full body not visible in every view</span>{/if}</div>
  <footer class="activity-ui bottom"><div class="control-centre">{#if !recording && countdown === null}<button class:ready={canStart()} class="start" onclick={() => void begin()}>START TEST <span>→</span></button>{:else if recording}<div class="recording"><i></i>RECORDING · {formatted(elapsed)} / {currentDuration()}s</div>{:else}<div class="arming">ARMING CAMERAS…</div>{/if}</div></footer>
  {#if recording}<div class="progress"><i style={`transform:scaleX(${Math.min(1, elapsed / currentDuration())})`}></i></div>{/if}{#if countdown !== null}<div class="countdown">{countdown}</div>{/if}{#if error}<div class="error" role="alert">{error}</div>{/if}
</main>

<style>
