margin-top:3px;color:#f8f8f6;font-size:clamp(25px,3vw,38px);line-height:1;letter-spacing:-.07em}.timer-readout strong i{color:#8ca0a5;font-size:.42em;font-style:normal;letter-spacing:-.03em}.top>div:last-child{justify-self:end;display:flex;gap:12px;align-items:center}.top>div>span{font-size:9px;color:#70e9c0;font-weight:800}.top>div>span.offline{color:#ff9d7f}.centre{top:50%;left:50%;width:min(320px,70vw);transform:translate(-50%,-50%);text-align:center}.silhouette{height:min(52vh,500px);border:2px dashed #f8f8f666;border-radius:48% 48% 24% 24%;opacity:.48}.instruction{margin:13px 0 0;font-size:11px;font-weight:800;line-height:1.45}.warning{display:inline-block;margin-top:8px;padding:7px 9px;background:#c9482d;color:#fff;font-size:9px;font-weight:800}.bottom{right:0;bottom:0;left:0;display:grid;grid-template-columns:1fr;place-items:center;padding:18px 24px;background:linear-gradient(transparent,#07171ce8)}.control-centre{display:grid;gap:10px;width:min(430px,100%)}.start{border:0;background:#f8f8f6;color:#07171c;padding:16px;font-weight:900;letter-spacing:.05em}.start.ready{background:#00c8f5}.start span{margin-left:16px;font-size:18px}.recording,.arming{padding:16px;background:#f8f8f6;color:#07171c;text-align:center;font-size:11px;font-weight:900}.recording i{display:inline-block;width:8px;height:8px;margin-right:8px;border-radius:50%;background:#ef4d3b;animation:pulse 1s infinite}.progress{position:absolute;z-index:6;right:0;bottom:0;left:0;height:6px;background:#ffffff30}.progress i{display:block;width:100%;height:100%;background:#00c8f5;transform-origin:left}.countdown{position:absolute;z-index:10;inset:0;display:grid;place-items:center;background:#07171c66;font-size:min(45vw,420px);font-weight:800;line-height:1;color:#00c8f5}.error{position:absolute;z-index:15;top:95px;left:50%;max-width:min(620px,90vw);padding:12px;background:#ffe9e4;color:#8c2b18;transform:translateX(-50%);font-size:12px;font-weight:800}@keyframes pulse{50%{opacity:.25;transform:scale(.7)}}@media(max-width:780px){.panel-grid,.panel-grid.two{display:flex;overflow-x:auto;scroll-snap-type:x mandatory}.capture-panel{flex:0 0 100%;scroll-snap-align:start}.capture-panel:not(.active){display:none}.mobile-view{display:block;right:12px;bottom:18%}.top{grid-template-columns:1fr auto;padding:15px}.timer-readout{grid-column:1/-1;grid-row:2;justify-self:center;margin-top:9px}.bottom{padding:12px}.centre{top:44%;width:48vw}.silhouette{height:38vh}.video-label{top:60px}.control-centre{width:100%}}@media(prefers-reduced-motion:reduce){.recording i{animation:none}}
  .bottom{display:grid;grid-template-columns:1fr;place-items:center;padding:18px 24px}
  .control-centre{width:min(430px,100%)}
  @media(max-width:780px){.bottom{padding:12px}.control-centre{width:100%}}
</style>
